// 27 m² apartment
// Generated by tools/migrate.mjs (Phase 1). build() adds this apartment's slabs, walls, floors and
// furniture to the shared scene; everything else comes from the engine.
import * as THREE from 'three';
import { PointerLockControls } from 'three/addons/controls/PointerLockControls.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { GTAOPass } from 'three/addons/postprocessing/GTAOPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { RectAreaLightUniformsLib } from 'three/addons/lights/RectAreaLightUniformsLib.js';
import { Sky } from 'three/addons/objects/Sky.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { X, Z } from '../engine/plan.js';
import {
  FACE, H, M, P, RBG, at, baseCabB, bedB, benchUphB, box, caneChairB, canvasTex, ceilingGroup, cove,
  curtain, cylinder, floatStandB, floor, flutedConsoleB, fridgeB, item, lathe, mesh, plantB,
  porcelainTex, railingBars, rainShower, rb, rug, sanca, std, succulent, tableLamp, terraceTex,
  tileBox, toiletB, towelRail, tvOnWall, upperCabB, vanity2B, wall, wardrobeB, woodClad, world,
} from '../engine/core.js';

export function build() {
  // ---------------------------------------------------------------------------
  // SLABS, FLOORS, CEILING
  // ---------------------------------------------------------------------------
  for (const [a, b, c, d] of [[751, 108, 1242, 953]]) {
    box(a, b, c, d, -0.3, 0, M.extWall, { collide: false });
    box(a, b, c, d, H, H + 0.3, M.extWall, { collide: false, parent: ceilingGroup });
    const w = X(c) - X(a), dd = Z(d) - Z(b);
    const ce = new THREE.Mesh(new THREE.PlaneGeometry(w, dd), M.ceiling);
    ce.rotation.x = Math.PI / 2; ce.position.set(X(a) + w / 2, H - 0.001, Z(b) + dd / 2); ce.receiveShadow = true;
    ceilingGroup.add(ce);
  }
  floor(775, 133, 1218, 742, porcelainTex, 0.9, 0.22);                   // cozinha + estar / dorm
  floor(775, 133, 950, 418, porcelainTex, 0.9, 0.25, 0.004);              // banho
  floor(775, 742, 1218, 912, terraceTex, 0.9, 0.5, 0.002);                // terraço

  // ---------------------------------------------------------------------------
  // WALLS (traced from the 27 m² plan)
  // ---------------------------------------------------------------------------
  wall(751, 108, 1242, 133, [{ from: 1012, to: 1116 }]);                  // FRONT DOOR (top of the kitchen)
  wall(751, 108, 775, 953);                                               // west façade
  wall(1218, 133, 1242, 953);                                             // east party wall
  wall(935, 133, 950, 425);                                               // banho | cozinha
  wall(775, 410, 950, 425, [{ from: 845, to: 902 }]);                     // banho door
  box(775, 133, 800, 215, 0, H, M.wall);                                  // shaft in the banho corner
  wall(775, 730, 1218, 755, [{ from: 885, to: 1015, top: 2.3, glass: 'open' }, { from: 1015, to: 1145, top: 2.3, glass: 'fixed' }]);  // sliding door → terraço
  curtain(1015, 1145, 730, -1);                                           // curtain only in front of the fixed glass (opening stays free)
  box(775, 755, 822, 912, 0, H, M.wall);                                  // gas heater niche
  box(822, 760, 824, 908, 0.05, 2.1, P.lacquer, { collide: false });      // its white door
  box(824, 830, 826, 838, 1.0, 1.15, P.black, { collide: false });
  railingBars(775, 912, 1218, 935);
  // front door leaf + handle
  box(1014, 117, 1114, 123, 0.005, 2.095, P.walnut);
  for (const [z0, z1] of [[123, 126], [114, 117]]) {
    box(1096, z0, 1099, z1, 0.98, 1.08, P.brass, { collide: false });
    box(1082, z0, 1099, z1, 1.02, 1.045, P.brass, { collide: false });
  }
  // building corridor / elevator lobby outside the front door
  box(751, -70, 1715, 108, -0.3, 0, M.extWall, { collide: false });
  floor(766, -55, 1700, 108, porcelainTex, 0.9, 0.22, 0.002);
  box(751, -70, 1715, 108, H, H + 0.3, M.extWall, { collide: false, parent: ceilingGroup });
  box(751, -70, 1715, 108, H - 0.012, H, M.ceiling, { collide: false, cast: false, parent: ceilingGroup });
  wall(751, -70, 1715, -55);
  wall(751, -55, 766, 108);
  wall(1700, -55, 1715, 108);
  wall(1242, 108, 1700, 133, [{ from: 1400, to: 1485 }]);                 // neighbour's door
  box(1402, 117, 1483, 123, 0.005, 2.095, P.walnut);
  for (const ex of [1150, 1280]) {
    box(ex, -55, ex + 101, -52, 0, 2.15, M.steel, { collide: false });
    box(ex + 50, -52.5, ex + 51, -51.7, 0.02, 2.13, P.black, { collide: false });
    box(ex + 108, -55, ex + 115, -53, 1.0, 1.25, P.black, { collide: false });
    box(ex + 110, -53.5, ex + 113, -52.4, 1.07, 1.1, P.led, { collide: false });
  }

  // ---------------------------------------------------------------------------
  // ---------------------------------------------------------------------------
  // HELPERS – framed art, roller blind on a wall running along z, wall sconce, round table
  // ---------------------------------------------------------------------------
  function artMat(bg, cols) {
    const t = canvasTex(512, 640, (g, w, h) => {
      g.fillStyle = bg; g.fillRect(0, 0, w, h);
      cols.forEach((c, i) => {
        g.fillStyle = c; g.globalAlpha = 0.85;
        g.beginPath();
        if (i % 3 === 0) g.arc(w * (0.3 + 0.4 * Math.random()), h * (0.25 + 0.5 * Math.random()), w * (0.16 + 0.12 * Math.random()), 0, Math.PI * 2);
        else if (i % 3 === 1) { const y = h * (0.45 + 0.35 * Math.random()); g.moveTo(0, y); g.bezierCurveTo(w * 0.3, y - h * 0.2, w * 0.7, y + h * 0.15, w, y - h * 0.05); g.lineTo(w, h); g.lineTo(0, h); }
        else g.rect(w * 0.15 * Math.random(), h * 0.1, w * (0.25 + 0.3 * Math.random()), h * 0.06);
        g.fill();
      });
      g.globalAlpha = 1;
    });
    t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
    return std({ map: t, roughness: 0.9 });
  }
  function wallArt(px, pz, w, h, yc, face, mat) {      // walnut float frame + print; face = direction it looks
    const g = new THREE.Group();
    rb(g, w, h, 0.03, P.walnut, 0, -h / 2, 0.015, 0.004);
    rb(g, w - 0.04, h - 0.04, 0.012, P.lacquer, 0, -h / 2 + 0.02, 0.026, 0.002);                   // mat board
    mesh(g, new THREE.PlaneGeometry(w - 0.1, h - 0.1), mat, 0, 0, 0.0335, 0, 0, 0, false);
    g.position.set(X(px), yc, Z(pz)); g.rotation.y = FACE[face]; world.add(g);
  }
  function rollerBlindZ(z0p, z1p, xWallP, dir, top = 2.2) {
    const z0 = Z(z0p), z1 = Z(z1p), xf = X(xWallP) + dir * 0.06, zc = (z0 + z1) / 2;
    mesh(world, RBG(0.08, 0.08, z1 - z0, 0.02), P.lacquer, xf, top - 0.04, zc);
    mesh(world, new THREE.PlaneGeometry(z1 - z0 - 0.04, 0.45), std({ color: '#e9e3d8', roughness: 1, side: THREE.DoubleSide, transparent: true, opacity: 0.92 }), xf, top - 0.3, zc, 0, Math.PI / 2, 0, false);
  }
  function sconce(px, pz, y, face) {                    // black wall arm + opal globe (emissive only, no extra light)
    const g = new THREE.Group();
    cylinder(g, 0.04, 0.04, 0.015, P.brass, 0, 0, 0.0075, 24).rotation.x = Math.PI / 2;
    mesh(g, new THREE.CylinderGeometry(0.007, 0.007, 0.14, 10), P.black, 0, 0, 0.08, Math.PI / 2);
    mesh(g, new THREE.SphereGeometry(0.065, 24, 16), P.shade, 0, 0.02, 0.17, 0, 0, 0, false);
    g.position.set(X(px), y, Z(pz)); g.rotation.y = FACE[face]; world.add(g);
  }
  function roundTableB(r = 0.4) {                    // walnut round top on a flared pedestal, succulent bowl
    const g = new THREE.Group(), top = 0.74;
    cylinder(g, r, r, 0.03, P.walnut, 0, top - 0.03, 0, 64);
    lathe(g, [[0, 0], [0.22, 0], [0.22, 0.02], [0.06, 0.06], [0.045, top - 0.08], [0.12, top - 0.035], [0, top - 0.035]], P.walnut, 0, 0, 0, 40);
    lathe(g, [[0, 0], [0.08, 0], [0.13, 0.06], [0.125, 0.065], [0, 0.02]], P.ceramic, 0, top, 0, 32);
    succulent(g, 0, top + 0.05, 0, 0.9);
    return g;
  }

  // ---------------------------------------------------------------------------
  // BANHO (1.35 × 2.35 m) – shower at the top with a glass screen, toilet and granite vanity on the
  // quartzite west wall with an LED cove
  // ---------------------------------------------------------------------------
  box(775, 230, 776.5, 410, 0, H, P.quartz, { collide: false }); cove(X(776.5), Z(230), Z(410), 1);
  item(toiletB, 777, 248, 845, 302, 'e');
  item(vanity2B, 777, 318, 832, 405, 'e');
  box(800, 226, 880, 230, 0, 2.0, M.glass, { cast: false }); box(878, 225, 882, 231, 0, 2.0, P.black, { collide: false });
  tileBox(800, 133, 935, 134.5, 0, H); tileBox(933.5, 134.5, 935, 228, 0, H); tileBox(800, 215, 801.5, 228, 0, H);
  tileBox(800, 134.5, 801.5, 215, 0, H);
  rainShower(870, 134.5, 870, 178);
  towelRail(935, 330, false, -1);
  box(902, 134.5, 933.5, 142, 1.05, 1.08, P.quartz, { collide: false });   // shower ledge
  [['#f2efe8', 0], ['#3b3a38', 1], ['#c9b79c', 2]].forEach(([c, i]) =>
    lathe(world, [[0, 0], [0.028, 0], [0.03, 0.17], [0.013, 0.2], [0, 0.2]], std({ color: c, roughness: 0.3 }), X(910 + i * 9), 1.08, Z(138.5), 20));

  // ---------------------------------------------------------------------------
  // COZINHA (2.20 × 5.05 m with the studio) – tall walnut pantry on the banho wall, fridge + granite
  // run with sink and cooktop on the east wall, uppers with hood + LED
  // ---------------------------------------------------------------------------
  item(wardrobeB, 952, 135, 1008, 425, 'e');
  item(fridgeB, 1125, 138, 1215, 228, 'w');
  item((w, d) => baseCabB(w, d, { sinkX: -0.41, cooktopX: 0.48, ovenX: 0.48, body: P.greige, door: P.freijo }), 1145, 232, 1218, 418, 'w');
  item((w, d) => upperCabB(w, d, { hoodX: 0.48 }), 1185, 232, 1218, 418, 'w', false);
  box(1216, 232, 1218, 418, 0.9, 1.6, P.quartz, { collide: false });     // stone backsplash

  // ---------------------------------------------------------------------------
  // ESTAR / DORM (3.75 m) – double bed with its head on a walnut panel wall between two nightstands,
  // upholstered bench at the foot, rounded rug; on the east wall two wardrobes with a TV niche between
  // ---------------------------------------------------------------------------
  rug(778, 435, 1072, 725, P.rug);
  woodClad(775, 440, 778, 725, 0, 1.3);                                   // walnut headboard wall
  box(775, 440, 779, 725, 1.3, 1.315, P.walnut, { collide: false });
  box(778, 445, 779, 720, 1.285, 1.295, P.led, { collide: false, cast: false });
  item(bedB, 779, 497, 1000, 668, 'e', true, { headH: 1.15, lumbar: false });   // no middle cushion (user, 2026-11-13)
  item(floatStandB, 779, 442, 832, 490, 'e'); item(floatStandB, 779, 675, 832, 722, 'e');
  tableLamp(X(805), 0.55, Z(466)); tableLamp(X(805), 0.55, Z(698));
  item(benchUphB, 1003, 502, 1048, 665, 'e');
  item(wardrobeB, 1148, 427, 1218, 512, 'w');
  item(wardrobeB, 1148, 655, 1218, 730, 'w');
  woodClad(1214, 512, 1218, 655, 0, H);                                   // walnut TV niche
  item(flutedConsoleB, 1180, 515, 1214, 652, 'w', false);
  tvOnWall(X(1214), Z(583), 1.11, 0.64, 1.3, -1);
  sanca(775, 425, 1148, 730, 32, 0.12);

  // ---------------------------------------------------------------------------
  // TERRAÇO (3.26 × 1.30 m) – laundry counter with tank + washer, gas-heater niche, round table
  // with two cane chairs
  // ---------------------------------------------------------------------------
  item((w, d) => baseCabB(w, d, { tankX: 0.34, washerX: -0.28, body: P.greige, door: P.freijo }), 824, 765, 895, 910, 'e');
  at(roundTableB, 1115, 840, 0, 0.36);
  at(caneChairB, 1060, 875, 2.14);
  at(caneChairB, 1165, 800, -0.9);
  { const pl = plantB(0, 0, 0.6, P.terracotta); pl.position.set(X(1195), 0, Z(890)); world.add(pl); }

}
